from pathlib import Path
p=Path(__file__).parent;data=(p/'data/dashboard.json').read_text()
html='''<!doctype html><html lang="th"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>STA-PHS Solar • กันยายน 2569</title><style>body{font:17px system-ui;background:#f7f5fb;color:#28203c;margin:0}main{max-width:1200px;margin:auto;padding:32px}h1{font-size:30px}h2{font-size:22px}section,.card{background:white;border:1px solid #e8e0f3;border-radius:16px;padding:22px;margin:16px 0}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.card{margin:0}.card strong{display:block;color:#672fa0;font-size:28px;margin:10px 0}small{color:#716680}.note{background:#fff4dd;padding:18px;border-radius:12px}table{border-collapse:collapse;width:100%;font-size:15px}th,td{text-align:left;padding:10px;border-bottom:1px solid #eee}th{background:#eee7f5}select,input{font:inherit;padding:9px;border:1px solid #ccc;border-radius:8px}a{color:#672fa0} .scroll{overflow:auto;max-height:480px}svg{width:100%;height:250px}.legend{color:#672fa0}@media(max-width:700px){main{padding:16px}.cards{grid-template-columns:1fr 1fr}.card strong{font-size:23px}}</style><main><small>STA-PHS · SolarEdge Monitoring exports</small><h1>พลังงานโซลาร์ กันยายน 2569</h1><p>ชุดข้อมูลไซต์หลัก 24 อินเวอร์เตอร์ · 30 วัน · 2,880 จุด · 720 ชั่วโมง</p><div class="cards" id="cards"></div><p class="note">รายชั่วโมงเป็นค่าประมาณจากกำลังไฟทุก 15 นาที ยอดรายเดือนใช้รายงานพลังงาน • ยังไม่รวมไซต์ TR 500 kVA • พบ Import = 0 ทั้งวันในวันที่ 18 กันยายน ไฟล์อินเวอร์เตอร์ที่แก้ไขแล้วครบเดือนกันยายน</p><section><h2>พลังงานรายวัน (kWh)</h2><p class="legend">ม่วง: ผลิตโซลาร์ · เทา: ใช้ไฟรวม</p><svg id="chart" viewBox="0 0 1100 250" role="img" aria-label="กราฟพลังงานผลิตและใช้ไฟรายวัน"></svg><div class="scroll"><table id="daily"></table></div></section><section><h2>ข้อมูลรายชั่วโมง</h2><label>เลือกวัน <input id="date" type="date" min="2026-09-01" max="2026-09-30" value="2026-09-01"></label><p><small>kW เฉลี่ยในชั่วโมง และ kWh ประมาณจาก 4 จุดข้อมูล</small></p><div class="scroll"><table id="hourly"></table></div></section><section><h2>ทุกไฟล์และพารามิเตอร์</h2><p>เปิด <a href="README.md">สรุปและข้อสังเกต</a> · <a href="data/hourly.csv">CSV รายชั่วโมง</a> · <a href="data/daily.csv">CSV รายวัน</a> · <a href="data/all_parameters_raw.csv">ทุกพารามิเตอร์</a> · <a href="data/inverter_monthly.csv">อินเวอร์เตอร์รายเดือน</a></p><div class="scroll"><table id="inventory"></table></div></section></main><script>const D=__DATA__;const fmt=x=>Number(x).toLocaleString('th-TH',{maximumFractionDigits:2});const esc=x=>String(x).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');const s=D.summary;document.querySelector('#cards').innerHTML=[['ผลิตโซลาร์',s['Inverters Produced_kWh'],'kWh'],['ใช้ไฟรวม',s['Consumed Energy_kWh'],'kWh'],['ซื้อจากกริด',s['Imported Energy_kWh'],'kWh'],['ใช้โซลาร์ในอาคาร',s.self_consumed_solar_kWh,'kWh'],['ส่งออกกริด',s['Exported Energy_kWh'],'kWh'],['โซลาร์ครอบคลุมโหลด',s.solar_share_pct,'%']].map(([l,v,u])=>`<div class="card">${l}<strong>${fmt(v)}</strong><small>${u}</small></div>`).join('');function table(id,heads,rows){document.querySelector(id).innerHTML='<thead><tr>'+heads.map(x=>'<th>'+esc(x)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join('')+'</tbody>'}table('#daily',['วัน','ผลิต kWh','ใช้ไฟ kWh','ซื้อไฟ kWh','ส่งออก kWh','แสง DIRECT (หน่วยต้นทาง)'],D.daily.map(r=>[r.date,...['Inverters Produced_kWh','Consumed Energy_kWh','Imported Energy_kWh','Exported Energy_kWh','irradiance_DIRECT_source_units'].map(k=>fmt(r[k]))]));function hours(){const date=document.querySelector('#date').value;table('#hourly',['เวลา','ผลิตเฉลี่ย kW','ใช้ไฟเฉลี่ย kW','ผลิตประมาณ kWh','ใช้ไฟประมาณ kWh','ซื้อไฟประมาณ kWh','ส่งออกประมาณ kWh'],D.hourly.filter(r=>r.timestamp.startsWith(date)).map(r=>[r.timestamp.slice(11),...['Production_mean_kW','Consumption_mean_kW','Production_estimated_kWh','Consumption_estimated_kWh','From Grid_estimated_kWh','To Grid_estimated_kWh'].map(k=>fmt(r[k]))]))}document.querySelector('#date').onchange=hours;hours();table('#inventory',['ไฟล์','แถว','ช่วงข้อมูล','พารามิเตอร์'],D.inventory.map(r=>['<a href="raw/Solar/'+encodeURIComponent(r.file)+'">'+esc(r.file)+'</a>',r.rows,esc((r.start||'ไม่ระบุ')+' — '+(r.end||'')),esc(r.columns.slice(1).join(', '))]));const max=Math.max(...D.daily.map(r=>r['Consumed Energy_kWh']));document.querySelector('#chart').innerHTML=D.daily.map((r,i)=>{const x=i*35+28,a=r['Consumed Energy_kWh']/max*200,b=r['Inverters Produced_kWh']/max*200;return `<rect x="${x}" y="${220-a}" width="24" height="${a}" fill="#d4ccdf"><title>${r.date}: ใช้ไฟ ${fmt(r['Consumed Energy_kWh'])} kWh</title></rect><rect x="${x}" y="${220-b}" width="12" height="${b}" fill="#7637b4"><title>${r.date}: ผลิต ${fmt(r['Inverters Produced_kWh'])} kWh</title></rect><text x="${x}" y="242" font-size="12">${i+1}</text>`}).join('');</script></html>'''
(p/'index.html').write_text(html.replace('__DATA__',data),encoding='utf-8')
